        }

        @Override
        public <T> T getParsedOptionValue(final String option, final Supplier<T> defaultValue) throws ParseException {
            this.lastOption = option;
            this.lastSupplier = defaultValue;
            @SuppressWarnings("unchecked")
            T value = (T) toReturn;
            return value;
        }
    }

    @Test
    public void testDelegationToStringOverload() throws Exception {
